fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    match kind {
        DTypeKind::Bool => {
            // Only the Bool data type
            dtype == NumpyDType::Bool
        }
        DTypeKind::SignedInteger => {
            // Int8, Int16, Int32, Int64
            matches!(
                dtype,
                NumpyDType::Int8
                    | NumpyDType::Int16
                    | NumpyDType::Int32
                    | NumpyDType::Int64
            )
        }
        DTypeKind::UnsignedInteger => {
            // UInt8, UInt16, UInt32, UInt64
            matches!(
                dtype,
                NumpyDType::UInt8
                    | NumpyDType::UInt16
                    | NumpyDType::UInt32
                    | NumpyDType::UInt64
            )
        }
        DTypeKind::Integral => {
            // Any signed or unsigned integer
            matches!(
                dtype,
                NumpyDType::Int8
                    | NumpyDType::Int16
                    | NumpyDType::Int32
                    | NumpyDType::Int64
                    | NumpyDType::UInt8
                    | NumpyDType::UInt16
                    | NumpyDType::UInt32
                    | NumpyDType::UInt64
            )
        }
        DTypeKind::RealFloating => {
            // Float16, Float32, Float64
            matches!(
                dtype,
                NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64
            )
        }
        DTypeKind::ComplexFloating => {
            // Complex64, Complex128
            matches!(dtype, NumpyDType::Complex64 | NumpyDType::Complex128)
        }
        DTypeKind::Numeric => {
            // Bool, any integer, any real floating-point, or any complex floating-point
            matches!(
                dtype,
                NumpyDType::Bool
                    | NumpyDType::Int8
                    | NumpyDType::Int16
                    | NumpyDType::Int32
                    | NumpyDType::Int64
                    | NumpyDType::UInt8
                    | NumpyDType::UInt16
                    | NumpyDType::UInt32
                    | NumpyDType::UInt64
                    | NumpyDType::Float16
                    | NumpyDType::Float32
                    | NumpyDType::Float64
                    | NumpyDType::Complex64
                    | NumpyDType::Complex128
            )
        }
    }
}